package multiuser

const pageTemplates = `
{{define "head"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Title}} · SiYuan</title><style>
:root{color-scheme:dark;font-family:Inter,system-ui,-apple-system,sans-serif;background:#171b22;color:#e9edf5}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at top,#263a58 0,#171b22 46rem)}main{width:min(100% - 2rem,68rem);margin:auto;padding:3rem 0}.card{max-width:28rem;margin:8vh auto;background:#202631;border:1px solid #394354;border-radius:16px;padding:2rem;box-shadow:0 20px 60px #0006}.brand{font-size:1.45rem;font-weight:700;color:#8ab4f8;margin:0 0 1.5rem}.muted{color:#adb7c5}.notice{padding:.8rem 1rem;border-radius:8px;margin:1rem 0}.error{background:#542d36;color:#ffdce0}.message{background:#173e35;color:#c7f5de}label{display:block;margin:1rem 0 .35rem;font-size:.9rem}input{width:100%;padding:.75rem;border:1px solid #526073;border-radius:8px;background:#161b23;color:inherit;font:inherit}button,.button{display:inline-block;border:0;border-radius:8px;padding:.75rem 1rem;background:#6ea8fe;color:#071426;font:inherit;font-weight:650;cursor:pointer;text-decoration:none}.secondary{background:#343e4e;color:#e9edf5}.danger{background:#bc4b5a;color:#fff}nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:2rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(16rem,1fr));gap:1rem}.workspace{background:#202631;border:1px solid #394354;border-radius:12px;padding:1.25rem}.workspace h2{margin:0 0 .4rem;font-size:1.1rem}.workspace form{display:inline}.actions{display:flex;gap:.6rem;flex-wrap:wrap;margin-top:1rem}small{display:block;margin-top:.5rem}.footer{margin-top:1.25rem;font-size:.9rem}@media(max-width:600px){main{padding:1rem}.card{margin:2rem auto;padding:1.4rem}}
</style></head><body>{{end}}
{{define "foot"}}</body></html>{{end}}
{{define "login"}}{{template "head" .}}<main><section class="card"><p class="brand">SiYuan</p><h1>Sign in</h1>{{if .Error}}<p class="notice error">{{.Error}}</p>{{end}}{{if .Message}}<p class="notice message">{{.Message}}</p>{{end}}<form method="post" action="/login"><label>Email</label><input name="email" type="email" autocomplete="email" required autofocus><label>Password</label><input name="password" type="password" autocomplete="current-password" required><p class="actions"><button>Sign in</button></p></form><p class="footer"><a href="/forgot-password">Forgot password?</a>{{if .Signup}} · <a href="/register">Create account</a>{{end}}</p></section></main>{{template "foot" .}}{{end}}
{{define "register"}}{{template "head" .}}<main><section class="card"><p class="brand">SiYuan</p><h1>Create account</h1>{{if .Error}}<p class="notice error">{{.Error}}</p>{{end}}<form method="post" action="/register"><label>Email</label><input name="email" type="email" autocomplete="email" required autofocus><label>Password</label><input name="password" type="password" autocomplete="new-password" minlength="12" required><small>Use at least 12 characters</small><p class="actions"><button>Create account</button></p></form><p class="footer"><a href="/login">Back to sign in</a></p></section></main>{{template "foot" .}}{{end}}
{{define "forgot"}}{{template "head" .}}<main><section class="card"><p class="brand">SiYuan</p><h1>Reset password</h1>{{if .Error}}<p class="notice error">{{.Error}}</p>{{end}}{{if .Message}}<p class="notice message">{{.Message}}</p>{{end}}<form method="post" action="/forgot-password"><label>Email</label><input name="email" type="email" autocomplete="email" required autofocus><p class="actions"><button>Send reset link</button></p></form><p class="footer"><a href="/login">Back to sign in</a></p></section></main>{{template "foot" .}}{{end}}
{{define "reset"}}{{template "head" .}}<main><section class="card"><p class="brand">SiYuan</p><h1>Choose a new password</h1>{{if .Error}}<p class="notice error">{{.Error}}</p>{{end}}<form method="post" action="/reset-password"><input type="hidden" name="token" value="{{.ResetToken}}"><label>New password</label><input name="password" type="password" autocomplete="new-password" minlength="12" required autofocus><p class="actions"><button>Update password</button></p></form></section></main>{{template "foot" .}}{{end}}
{{define "dashboard"}}{{template "head" .}}<main><nav><div><p class="brand">SiYuan</p><strong>{{.User.Email}}</strong></div><form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="secondary">Sign out</button></form></nav>{{if .Error}}<p class="notice error">{{.Error}}</p>{{end}}{{if .Message}}<p class="notice message">{{.Message}}</p>{{end}}<section class="workspace"><h2>Create workspace</h2><form method="post" action="/workspaces"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Name</label><input name="name" required maxlength="100"><label>Address</label><input name="slug" required pattern="[a-z][a-z0-9-]{2,62}" placeholder="team-notes"><small>It becomes your subdomain</small><p class="actions"><button>Create workspace</button></p></form></section><h1>Your workspaces</h1><section class="grid">{{range .Workspaces}}<article class="workspace"><h2>{{.Name}}</h2><p class="muted">{{.Slug}} · {{.Role}}{{if .Active}} · active{{end}}</p><form method="post" action="/workspaces/{{.ID}}/open"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button>Open</button></form>{{if eq .Role "owner"}}<details><summary>Manage</summary><form method="post" action="/workspaces/{{.ID}}/rename"><input type="hidden" name="csrf" value="{{$.CSRF}}"><label>New name</label><input name="name" value="{{.Name}}" required><p><button class="secondary">Rename</button></p></form><form method="post" action="/workspaces/{{.ID}}/delete"><input type="hidden" name="csrf" value="{{$.CSRF}}"><label>Type “{{.Name}}” to delete</label><input name="confirm" required><p><button class="danger">Delete workspace</button></p></form></details>{{end}}</article>{{else}}<p class="muted">No workspaces are available.</p>{{end}}</section></main>{{template "foot" .}}{{end}}
`
